function installUniversalTableTools(){
  const tables = $$('#content .data-card table, #content .table-panel table');
  tables.forEach((table,index)=>{
    const card=table.closest('.data-card')||table.closest('.table-panel');
    if(!card || card.dataset.universalTools==='1') return;
    const headers=$$('thead th',table);
    const body=$('tbody',table);
    if(!headers.length||!body) return;
    card.dataset.universalTools='1';
    const tool=document.createElement('div');
    tool.className='universal-table-tools';
    const fieldOptions=headers.map((h,i)=>`<option value="${i}">${esc(h.innerText.trim()||`Column ${i+1}`)}</option>`).join('');
    tool.innerHTML=`
      <div class="table-tool-search"><i class="fa-solid fa-magnifying-glass"></i><input type="search" class="ut-search" placeholder="Search all columns…"></div>
      <select class="ut-field" aria-label="Filter field"><option value="all">Filter any field</option>${fieldOptions}</select>
      <select class="ut-value" aria-label="Filter value"><option value="">All values</option></select>
      <select class="ut-sort-field" aria-label="Sort by"><option value="">Sort by…</option>${fieldOptions}</select>
      <select class="ut-sort-dir" aria-label="Sort direction"><option value="asc">Ascending ↑</option><option value="desc">Descending ↓</option></select>
      <button type="button" class="secondary-btn ut-reset"><i class="fa-solid fa-rotate-left"></i> Reset</button>`;
    card.insertBefore(tool,table.parentElement);
    const search=$('.ut-search',tool), field=$('.ut-field',tool), value=$('.ut-value',tool);
    const sortField=$('.ut-sort-field',tool), sortDir=$('.ut-sort-dir',tool);
    const rows=()=>$$('tbody tr',table);
    const norm=s=>(s||'').replace(/\s+/g,' ').trim().toLocaleLowerCase();
    function refreshValues(){
      const col=field.value;
      const previous=value.value;
      const vals=col==='all'?[]:[...new Set(rows().map(r=>norm(r.cells[col]?.innerText)).filter(Boolean))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));
      value.innerHTML='<option value="">All values</option>'+vals.map(v=>`<option value="${esc(v)}">${esc(v.length>42?v.slice(0,42)+'…':v)}</option>`).join('');
      if(vals.includes(previous)) value.value=previous;
    }
    function apply(){
      const q=norm(search.value), col=field.value, exact=norm(value.value);
      rows().forEach(row=>{
        const cells=[...row.cells];
        const searchMatch=!q||norm(row.innerText).includes(q);
        const fieldText=col==='all'?norm(row.innerText):norm(cells[Number(col)]?.innerText);
        const valueMatch=!exact||fieldText===exact;
        row.style.display=searchMatch&&valueMatch?'':'none';
      });
      if(sortField.value!==''){
        const index=Number(sortField.value),direction=sortDir.value==='desc'?-1:1;
        const sorted=rows().sort((a,b)=>{
          const av=norm(a.cells[index]?.innerText),bv=norm(b.cells[index]?.innerText);
          const an=Number(av.replace(/[^\d.-]/g,'')),bn=Number(bv.replace(/[^\d.-]/g,''));
          const numeric=av!==''&&bv!==''&&Number.isFinite(an)&&Number.isFinite(bn)&&/^-?[\d,.₹$ ]+$/.test(av)&&/^-?[\d,.₹$ ]+$/.test(bv);
          return (numeric?an-bn:av.localeCompare(bv,undefined,{numeric:true,sensitivity:'base'}))*direction;
        });
        sorted.forEach(row=>body.appendChild(row));
      }
    }
    field.addEventListener('change',()=>{refreshValues();apply()});
    value.addEventListener('change',apply);
    search.addEventListener('input',apply);
    sortField.addEventListener('change',apply);
    sortDir.addEventListener('change',apply);
    $('.ut-reset',tool).addEventListener('click',()=>{
      search.value='';field.value='all';sortField.value='';sortDir.value='asc';refreshValues();value.value='';apply();
    });
    refreshValues();
  });
}

function render(){page=page||'dashboard';$$('.nav-link[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#crumb').textContent=page[0].toUpperCase()+page.slice(1);let html=page==='dashboard'?dashboard():page==='students'?pageStudents():page==='classes'?pageClasses():page==='teachers'?pageTeachers():page==='attendance'?pageAttendance():page==='fees'?pageFees():page==='library'?pageLibrary():['exams','timetable','homework','transport','notices'].includes(page)?genericPage():reportsOrSettings();$('#content').innerHTML=html;save();installUniversalTableTools();wirePage();if(page==='dashboard')drawCharts()}
function drawCharts(){Object.values(charts).forEach(c=>c.destroy());charts={};if(!window.Chart)return;let text=getComputedStyle(document.body).getPropertyValue('--muted').trim(),grid=getComputedStyle(document.body).getPropertyValue('--line').trim();let months=['Jun','Jul','Aug','Sep','Oct','Nov'];let totals=months.map((m,i)=>db.fees.filter(f=>new Date(f.date).getMonth()===i+5).reduce((a,f)=>a+f.paid,0));charts.fee=new Chart($('#feeChart'),{type:'bar',data:{labels:months,datasets:[{label:'Collected',data:totals,backgroundColor:'#766cf0',borderRadius:7,maxBarThickness:25}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false},ticks:{color:text,font:{size:9}}},y:{grid:{color:grid},ticks:{color:text,font:{size:9},callback:v=>'₹'+v}}}}});let a=db.attendance.filter(x=>x.date===today),counts=['Present','Absent','Late','On Leave'].map(s=>a.filter(x=>x.status===s).length);charts.att=new Chart($('#attendanceChart'),{type:'doughnut',data:{labels:['Present','Absent','Late','On leave'],datasets:[{data:counts.some(Boolean)?counts:[1,0,0,0],backgroundColor:['#22b58b','#ef7182','#efb34c','#8b83ed'],borderWidth:0,hoverOffset:5}]},options:{responsive:true,maintainAspectRatio:false,cutout:'72%',plugins:{legend:{position:'bottom',labels:{color:text,usePointStyle:true,boxWidth:7,font:{size:9},padding:13}}}}})}
