exams:[['title','Examination name','text'],['className','Class','text'],['date','Exam date','date'],['subject','Subjects','text']],
timetable:[['className','Class','text'],['day','Day','select',['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday']],['period','Period','text'],['subject','Subject','text'],['teacher','Teacher','select',db.teachers.map(t=>t.name)],['room','Room','text']],
homework:[['title','Assignment title','text'],['className','Class','text'],['subject','Subject','text'],['due','Due date','date'],['teacher','Teacher','text']],
